def solve(nums, target):
    seen = {}
    answer = None
    for i in range(len(nums) - 1, -1, -1):
        complement = target - nums[i]
        if complement in seen:
            answer = [i, seen[complement]]
        seen[nums[i]] = i
    return answer if answer is not None else []
